import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(1200);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/desk1.jpg', type: 'jpeg', quality: 80 });
// simulate a slice across the sponge
const box = await page.locator('#game').boundingBox();
const cx = box.x + box.width / 2, cy = box.y + box.height * 0.53;
await page.mouse.move(cx - 120, cy - 50);
await page.mouse.down();
for (let i = 0; i <= 24; i++) {
  const x = cx - 120 + i * 10;
  const y = cy - 50 + Math.sin(i / 3) * 45;
  await page.mouse.move(x, y);
  await page.waitForTimeout(8);
}
await page.mouse.up();
await page.waitForTimeout(250);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/desk2.jpg', type: 'jpeg', quality: 80 });
console.log('errors:', JSON.stringify(errors));
console.log('strokes:', await page.evaluate(() => document.querySelector('#toast').textContent));
await browser.close();

import { createRequire } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(1200);
const info = await page.evaluate(() => {
  const c = document.querySelector('#game');
  const ctx = c.getContext('2d');
  const { data } = ctx.getImageData(0, 0, c.width, c.height);
  let whites = 0, minx = 1e9, maxx = -1, miny = 1e9, maxy = -1;
  for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++) {
    const i = (y * c.width + x) * 4;
    if (data[i] > 250 && data[i+1] > 250 && data[i+2] > 248 && data[i+3] > 250) { whites++; if (x<minx)minx=x; if(x>maxx)maxx=x; if(y<miny)miny=y; if(y>maxy)maxy=y; }
  }
  const elems = [...document.querySelectorAll('*')].map(e => { const r = e.getBoundingClientRect(); return [e.tagName, e.id, Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height), getComputedStyle(e).backgroundColor]; }).filter(a => a[6] === 'rgb(255, 255, 255)');
  return { w: c.width, h: c.height, whites, minx, maxx, miny, maxy, elems };
});
console.log(JSON.stringify(info, null, 1));
const dataUrl = await page.evaluate(() => document.querySelector('#game').toDataURL('image/png'));
writeFileSync('/home/runner/work/PlayGround/PlayGround/screenshots/canvas.png', Buffer.from(dataUrl.split(',')[1], 'base64'));
await browser.close();

