const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
for (const mode of ['headed-pause', 'headless']) {
  const browser = await chromium.launch({ ...config.browser.launchOptions, headless: mode === 'headless', timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  if (mode === 'headed-pause') {
    await page.addInitScript(() => {
      const orig = window.requestAnimationFrame.bind(window);
      let paused = false;
      window.requestAnimationFrame = cb => { if (paused) return 0; return orig(t => { if (!paused) cb(t); }); };
      window.__pauseFrames = () => { paused = true; };
    });
  }
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(1500);
  if (mode === 'headed-pause') { await page.evaluate(() => window.__pauseFrames()); await page.waitForTimeout(700); }
  await page.screenshot({ path: `/home/runner/work/PlayGround/PlayGround/screenshots/test-${mode}.jpg`, type: 'jpeg', quality: 80 });
  await browser.close();
}

