import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(1200);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile1.jpg', type: 'jpeg', quality: 80 });
const box = await page.locator('#game').boundingBox();
const cx = box.x + box.width / 2, cy = box.y + box.height * 0.53;
await page.mouse.move(cx - 65, cy - 40);
await page.mouse.down();
for (let i = 0; i <= 16; i++) { await page.mouse.move(cx - 65 + i * 8, cy - 40 + Math.sin(i / 2.5) * 26); await page.waitForTimeout(10); }
await page.mouse.up();
await page.waitForTimeout(300);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile2.jpg', type: 'jpeg', quality: 80 });
const info = await page.evaluate(() => ({
  scrollW: document.documentElement.scrollWidth, innerW: innerWidth,
  scrollH: document.documentElement.scrollHeight, innerH: innerHeight,
  buttons: [...document.querySelectorAll('button')].map(b => { const r = b.getBoundingClientRect(); return [b.textContent.trim(), Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)]; }),
  hint: (() => { const r = document.querySelector('#hint').getBoundingClientRect(); return [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)]; })()
}));
console.log(JSON.stringify({ errors, info }, null, 1));
await browser.close();

