#toast{position:absolute;top:104px;left:50%;transform:translate(-50%,-8px);padding:9px 16px;border-radius:99px;background:#1c5052;color:#fff4d8;font:800 12px Nunito,sans-serif;opacity:0;transition:opacity .3s,transform .3s;pointer-events:none;white-space:normal;text-align:center;max-width:min(92vw,540px);z-index:6;box-shadow:0 6px 20px #194a4b33}
#toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:620px){
  .topbar{align-items:flex-start;padding:14px 14px}
  .brand p{max-width:152px;font-size:10.5px;line-height:1.35;margin-top:4px}
  .eyebrow{display:none}
  .actions{gap:5px}
  .pill{padding:9px 11px;font-size:10.5px;border-width:1.5px;min-height:40px}
  .pill.icon{font-size:15px;padding:5px 9px;min-width:34px;min-height:40px}
  .caption{display:none}
  .hint{font-size:10.5px;bottom:max(14px,env(safe-area-inset-bottom));padding:9px 13px;max-width:92vw}
  #toast{top:88px;font-size:11px;padding:8px 14px}
}
@media(max-width:380px){
  .pill{padding:8px 8px;font-size:10px}
  .brand h1{font-size:19px}
}

