import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
const page = await context.newPage();
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(1300);
// sound on
await page.click('#sound');
const soundOn = await page.getAttribute('#sound', 'aria-pressed');
// touch slice across sponge
const box = await page.locator('#game').boundingBox();
const cx = box.x + box.width / 2, cy = box.y + box.height * 0.53;
const client = await context.newCDPSession(page);
await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: cx - 80, y: cy - 55, id: 1 }] });
for (let i = 0; i <= 20; i++) {
  await client.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: cx - 80 + i * 8, y: cy - 55 + Math.sin(i / 2.4) * 34, id: 1 }] });
  await page.waitForTimeout(9);
}
await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
await page.waitForTimeout(320);
const toastAfterSlice = await page.textContent('#toast');
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/touch.jpg', type: 'jpeg', quality: 80 });
// undo then reset
await page.click('#undo');
const toastUndo = await page.textContent('#toast');
await page.click('#reset');
const toastReset = await page.textContent('#toast');
// narrow viewport
await page.setViewportSize({ width: 320, height: 568 });
await page.waitForTimeout(400);
const narrow = await page.evaluate(() => ({
  scrollW: document.documentElement.scrollWidth,
  buttons: [...document.querySelectorAll('.pill')].map(b => { const r = b.getBoundingClientRect(); return { text: b.textContent.trim(), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; }),
  brand: (() => { const r = document.querySelector('.brand').getBoundingClientRect(); return { x: Math.round(r.x), w: Math.round(r.width), h: Math.round(r.height) }; })(),
  hint: (() => { const r = document.querySelector('#hint').getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; })()
}));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/narrow.jpg', type: 'jpeg', quality: 80 });
console.log(JSON.stringify({ errors, soundOn, toastAfterSlice, toastUndo, toastReset, narrow }, null, 1));
await browser.close();

