import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(1400);
const box = await page.locator('#game').boundingBox();
const cx = box.x + box.width / 2, cy = box.y + box.height * 0.525;
// miss on empty sand
await page.mouse.move(60, 700); await page.mouse.down();
for (let i = 0; i < 8; i++) await page.mouse.move(60 + i * 8, 700 - i * 5);
await page.mouse.up(); await page.waitForTimeout(200);
const afterMiss = { debug: await page.evaluate(() => window.__spongeDebug()), toast: await page.textContent('#toast') };
// cross the sponge starting outside
await page.mouse.move(cx - 220, cy + 20); await page.mouse.down();
for (let i = 0; i <= 44; i++) { await page.mouse.move(cx - 220 + i * 10, cy + 20 + Math.sin(i / 7) * 30); await page.waitForTimeout(6); }
await page.mouse.up(); await page.waitForTimeout(250);
const afterCross = { debug: await page.evaluate(() => window.__spongeDebug()), toast: await page.textContent('#toast') };
// single tap
await page.mouse.move(cx + 30, cy - 70); await page.mouse.down(); await page.mouse.up(); await page.waitForTimeout(200);
const afterTap = await page.evaluate(() => window.__spongeDebug());
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-desktop.jpg', type: 'jpeg', quality: 82 });
// undo twice
await page.click('#undo'); await page.waitForTimeout(150);
await page.click('#undo'); await page.waitForTimeout(150);
const afterUndo = await page.evaluate(() => window.__spongeDebug());
console.log(JSON.stringify({ errors, afterMiss, afterCross, afterTap, afterUndo }, null, 1));
await browser.close();

