import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(1500);
const box = await page.locator('#game').boundingBox();
const cx = box.x + box.width / 2, cy = box.y + box.height * 0.525;
async function cut(x1, y1, x2, y2, amp = 0, n = 26) {
  await page.mouse.move(x1, y1);
  await page.mouse.down();
  for (let i = 0; i <= n; i++) {
    const f = i / n;
    await page.mouse.move(x1 + (x2 - x1) * f, y1 + (y2 - y1) * f + Math.sin(f * Math.PI * 2) * amp);
    await page.waitForTimeout(8);
  }
  await page.mouse.up();
  await page.waitForTimeout(220);
}
// main cut: across the exposed middle, below the face
await cut(cx - 150, cy - 32, cx + 145, cy + 55, 5);
// small nick on the right shoulder
await cut(cx + 72, cy - 92, cx + 86, cy - 56, 0, 10);
await page.waitForTimeout(420);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/hero.jpg', type: 'jpeg', quality: 82 });
console.log(JSON.stringify({ errors }));
await browser.close();

