import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];
const results = {};
for (const [name, w, h] of [['desktop', 1280, 800], ['mobile', 390, 844], ['narrow', 320, 568], ['landscape', 844, 390]]) {
  const page = await browser.newPage({ viewport: { width: w, height: h }, hasTouch: name !== 'desktop' });
  page.on('pageerror', e => errors.push(name + ': ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(name + ': ' + m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(1200);
  const box = await page.locator('#game').boundingBox();
  const cx = box.x + box.width / 2, cy = box.y + box.height * 0.525;
  if (name === 'desktop' || name === 'mobile') {
    await page.mouse.move(cx - box.width * .22, cy - 24);
    await page.mouse.down();
    for (let i = 0; i <= 20; i++) { await page.mouse.move(cx - box.width * .22 + i * box.width * .022, cy - 24 + Math.sin(i / 3) * 20); await page.waitForTimeout(7); }
    await page.mouse.up();
    await page.waitForTimeout(200);
    await page.click('#undo');
  }
  if (name === 'mobile' || name === 'narrow') {
    await page.click('#sound');
    await page.click('#reset');
  }
  const layout = await page.evaluate(() => ({
    sw: document.documentElement.scrollWidth, iw: innerWidth,
    resetLabel: getComputedStyle(document.querySelector('#reset .long')).display === 'none' ? 'Reset' : 'Start fresh',
    buttons: [...document.querySelectorAll('.pill')].map(b => { const r = b.getBoundingClientRect(); return [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)]; })
  }));
  results[name] = layout;
  await page.waitForTimeout(200);
  if (name === 'desktop') await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-check.jpg', type: 'jpeg', quality: 82 });
  await page.close();
}
console.log(JSON.stringify({ errors, results }, null, 1));
await browser.close();

